function applyFix(item, action) { const proposal = action.startsWith("custom:") ? proposals(item).find((entry) => entry.id === action.slice(7)) : null; const originals = item.rows.map((row) => ({ row, value: row[item.column] })); if (action === "convert") item.rows.forEach((row) => { if (Number(row[item.column]) > 1) row[item.column] = (Number(row[item.column]) / 100).toFixed(4); }); if (["imputeMedian", "imputeMean"].includes(action)) item.rows.forEach((row) => row[item.column] = numericSimulation(item, action).fill.toFixed(2)); if (action === "standardize") item.rows.forEach((row) => { if (String(row.channel).replace(/[ _-]/g, "").toLowerCase() === "paidsocial") row.channel = "Paid Social"; }); if (action === "mapOnly") item.rows.forEach((row) => { if (row.channel === "paid_social") row.channel = "Paid Social"; }); if (action === "date") item.rows.forEach((row) => { const [month, day, year] = row.launch_date.split("/"); row.launch_date = `${year}-${month.padStart(2, "0")}-${day.padStart(2, "0")}`; }); if (proposal?.operation === "fill") item.rows.forEach((row) => row[item.column] = proposal.value.toFixed(2)); if (proposal?.mapping) item.rows.forEach((row) => { if (proposal.mapping[row[item.column]]) row[item.column] = proposal.mapping[row[item.column]]; }); item.status = ["valid", "keep"].includes(action) ? "valid" : "finalized"; state.changes.unshift({ id: Date.now(), issue: item, title: proposal ? "Custom AI proposal" : action, rows: item.rows, before: originals.slice(0, 3).map((entry) => entry.value).join(", "), after: item.rows.slice(0, 3).map((row) => row[item.column]).join(", "), reason: proposal?.interpretation || item.summary, originals }); state.selectedIssue = null; notify("Decision finalized and added to history."); render(); }
